// Generates src/generated/openapi.ts from docs/api/openapi.yaml (ARC owns the contract).
// `pnpm --filter @ottimo/api-client gen` after every contract change; the drift test fails CI when stale.
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';
import prettier from 'prettier';

export const SPEC_URL = new URL('../../../docs/api/openapi.yaml', import.meta.url);
export const OUT_URL = new URL('../src/generated/openapi.ts', import.meta.url);

const HEADER =
  '// GENERATED by packages/api-client/scripts/gen.mjs from docs/api/openapi.yaml – do not edit by hand.\n\n';

export async function generate() {
  const ast = await openapiTS(SPEC_URL, { alphabetize: false });
  const source = HEADER + astToString(ast);
  const options = (await prettier.resolveConfig(fileURLToPath(OUT_URL))) ?? {};
  return prettier.format(source, { ...options, parser: 'typescript' });
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const next = await generate();
  const prev = await readFile(OUT_URL, 'utf8').catch(() => '');
  if (prev !== next) await writeFile(OUT_URL, next);
  console.log(prev === next ? 'openapi.ts up to date' : 'openapi.ts regenerated');
}
